INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Lilith', 'Pluto', 'semi-square', 'Góc chiếu Semi-Square giữa Lilith và Pluto thể hiện sự tương tác năng lượng giữa hai hành tinh Lilith và Pluto.', 'Trong cuộc sống hàng ngày, góc chiếu này tạo ra sự kết nối trực tiếp giữa năng lượng Lilith và biểu hiện của Pluto.', 'Khả năng thích ứng cao, thấu hiểu tâm lý và phát huy sức mạnh tổng hợp từ Lilith và Pluto.', 'Cần học cách cân bằng và hòa hợp nhu cầu của Lilith và Pluto để tránh xung đột nội tâm.', '', '', ARRAY['Lilith', 'Pluto', 'semi-square']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO NOTHING;
